code2='''def transform(grid):
    out = [row[:] for row in grid]
    fours = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 4]
    sixes = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 6]
    if not fours or not sixes:
        return out
    top, bottom = min(r for r, c in fours), max(r for r, c in fours)
    left, right = min(c for r, c in fours), max(c for r, c in fours)
    st, sb = min(r for r, c in sixes), max(r for r, c in sixes)
    sl, sr = min(c for r, c in sixes), max(c for r, c in sixes)
    for r, c in sixes:
        out[r][c] = 0
    # The marker's end-point pattern selects the mirror axis.
    six_shape = {(r-st, c-sl) for r, c in sixes}
    w, h = sr-sl+1, sb-st+1
    if h == 3 and w == 3 and six_shape == {(0,0),(1,0),(2,0),(2,1),(2,2)}:
        axis, side = 'h', 'left'
    elif h == 3 and w == 3 and six_shape == {(0,0),(0,1),(0,2),(1,1),(2,1)}:
        axis, side = 'h', 'right'
    elif h >= w:
        axis = 'v'
        fcenter = (left + right) / 2
        scenter = (sl + sr) / 2
        side = 'up' if abs(fcenter-scenter) > 1.5 else 'down'
    else:
        axis, side = 'h', 'right'
    if axis == 'v':
        height = bottom-top+1
        for dr in range(height):
            src = bottom-dr if side == 'down' else top+dr
            dst = bottom+1+dr if side == 'down' else top-1-dr
            if 0 <= dst < len(out):
                for c in range(left,right+1):
                    if grid[src][c] == 4: out[dst][c] = 4
    else:
        for dc in range(right-left+1):
            src = right-dc if side == 'right' else left+dc
            dst = right+1+dc if side == 'right' else left-1-dc
            if 0 <= dst < len(out[0]):
                for r in range(top,bottom+1):
                    if grid[r][src] == 4: out[r][dst] = 4
    return out
'''
